journals.script:
{
is_shown_when_inactive = {
	has_variable = ywc_v03_initialized
	NOT = { has_variable = ywc_c01_started }
	OR = {
		AND = { c:SHU ?= this OR = { ywc_c01_case_ready_shu = yes var:ywc_c01_case_open ?= 1 } }
		AND = { c:JHG ?= this OR = { ywc_c01_case_ready_jhg = yes var:ywc_c01_case_open ?= 1 } }
		AND = { OR = { c:KOR ?= this c:DMG ?= this } var:ywc_c01_case_open ?= 1 }
	}
}
possible = {
	has_variable = ywc_v03_initialized
	ywc_v03_has_capacity = yes
	NOT = { has_variable = ywc_c01_started }
	OR = {
		AND = { c:SHU ?= this ywc_c01_case_ready_shu = yes }
		AND = { c:JHG ?= this OR = { ywc_c01_case_ready_jhg = yes var:ywc_c01_case_open ?= 1 } }
		AND = { OR = { c:KOR ?= this c:DMG ?= this } var:ywc_c01_case_open ?= 1 }
	}
}
immediate = {
	if = { limit = { NOT = { has_variable = ywc_c01_started } }
		set_variable = { name = ywc_c01_started value = 1 }
		set_variable = { name = ywc_c01_popup_epoch value = 0 }
		set_variable = { name = ywc_c01_wait_age value = 0 }
		change_variable = { name = ywc_v03_active_arc_count add = 1 }
		change_variable = { name = ywc_v03_visible_task_count add = 1 }
	}
	if = { limit = { NOT = { has_variable = ywc_c01_popup_epoch } } set_variable = { name = ywc_c01_popup_epoch value = 0 } }
	if = { limit = { c:SHU ?= this NOT = { has_variable = ywc_c01_role } } set_variable = { name = ywc_c01_role value = 1 } }
	if = { limit = { OR = { c:KOR ?= this c:DMG ?= this } NOT = { has_variable = ywc_c01_role } } set_variable = { name = ywc_c01_role value = 3 } }
	if = { limit = { c:JHG ?= this NOT = { has_variable = ywc_c01_role } } if = { limit = { c:SHU ?= { is_country_alive = yes } } set_variable = { name = ywc_c01_role value = 2 } } else = { set_variable = { name = ywc_c01_role value = 4 } } }
	if = { limit = { OR = { var:ywc_c01_role ?= 1 var:ywc_c01_role ?= 4 } NOT = { has_variable = ywc_c01_stage } }
		set_variable = { name = ywc_c01_case_open value = 1 }
		set_variable = { name = ywc_c01_stage value = 1000 }
		set_variable = { name = ywc_c01_pending value = 1000 }
	}
	if = { limit = { OR = { var:ywc_c01_role ?= 2 var:ywc_c01_role ?= 3 } NOT = { has_variable = ywc_c01_stage } } set_variable = { name = ywc_c01_stage value = 1018 } }
	if = { limit = { c:SHU ?= this c:JHG ?= { is_country_alive = yes NOT = { has_variable = ywc_c01_case_open } } }
		c:JHG = { set_variable = { name = ywc_c01_case_open value = 1 } set_variable = { name = ywc_c01_role value = 2 } set_variable = { name = ywc_c01_popup_epoch value = 0 } set_variable = { name = ywc_c01_wait_age value = 0 } set_variable = { name = ywc_c01_stage value = 1018 } }
	}
}
on_monthly_pulse = {
	effect = {
		if = { limit = { OR = { var:ywc_c01_role ?= 1 var:ywc_c01_role ?= 4 } var:ywc_c01_stage ?= 1013 }
			change_variable = { name = ywc_c01_wait_age add = 1 }
			if = { limit = { OR = { ywc_c01_responses_resolved = yes var:ywc_c01_wait_age >= 12 } } ywc_c01_init_after_responses = yes }
		}
		if = { limit = { OR = { var:ywc_c01_role ?= 2 var:ywc_c01_role ?= 3 } var:ywc_c01_stage ?= 1018 }
			change_variable = { name = ywc_c01_wait_age add = 1 }
			if = { limit = { OR = { ywc_c01_initiator_gone = yes var:ywc_c01_wait_age >= 36 } } ywc_c01_close_no_talks = yes }
		}
		if = { limit = { OR = { var:ywc_c01_role ?= 2 var:ywc_c01_role ?= 3 } OR = { var:ywc_c01_stage ?= 1002 var:ywc_c01_stage ?= 1003 } NOT = { ywc_c01_initiator_awaiting_responses = yes } }
			ywc_c01_close_no_talks = yes
		}
		if = { limit = { var:ywc_c01_stage ?= 1014 }
			change_variable = { name = ywc_c01_wait_age add = 1 }
			if = { limit = { OR = { ywc_c01_initiator_gone = yes var:ywc_c01_wait_age >= 24 } }
				set_variable = { name = ywc_c01_review_open value = 1 }
				set_variable = { name = ywc_c01_stage value = 1009 }
				set_variable = { name = ywc_c01_pending value = 1009 }
				set_variable = { name = ywc_c01_wait_age value = 0 }
				change_variable = { name = ywc_c01_popup_epoch add = 1 }
			}
		}
		if = { limit = { ywc_c01_shu_delivery_1000 = yes } trigger_event = { id = ywc_crisis.1000 } }
		if = { limit = { ywc_c01_jhg_delivery_1000 = yes } trigger_event = { id = ywc_crisis.1000 } }
		if = { limit = { ywc_c01_shu_delivery_1001 = yes } trigger_event = { id = ywc_crisis.1001 } }
		if = { limit = { ywc_c01_jhg_delivery_1001 = yes } trigger_event = { id = ywc_crisis.1001 } }
		if = { limit = { ywc_c01_jhg_delivery_1002 = yes } trigger_event = { id = ywc_crisis.1002 } }
		if = { limit = { ywc_c01_kor_delivery_1003 = yes } trigger_event = { id = ywc_crisis.1003 } }
		if = { limit = { ywc_c01_dmg_delivery_1003 = yes } trigger_event = { id = ywc_crisis.1003 } }
	}
}
}

