				set_variable = { name = ywc_c01_aftermath value = 1 }
				set_variable = { name = ywc_c01_stage value = 1016 }
				set_variable = { name = ywc_c01_wait_age value = 0 }
				if = { limit = { has_variable = ywc_c01_pending } remove_variable = ywc_c01_pending }
				ywc_c01_release_capacity = yes
			}
		}
		if = { limit = { ywc_c01_shu_delivery_1006 = yes } trigger_event = { id = ywc_crisis.1006 } }
